// ListLists runs the :many query against sqlite.
func (q *sqliteQueries) ListLists(ctx context.Context, db DBTX, arg ListListsParams) ([]ListListsRow, error) {
	rows, err := db.QueryContext(ctx, q.listLists,
		timeTextPtr(arg.CreatedAfter),
		timeTextPtr(arg.CreatedBefore),
		timeTextPtr(arg.UpdatedAfter),
		timeTextPtr(arg.UpdatedBefore),
		arg.IncludeArchived,
		arg.Scope,
		arg.PageCursor,
		arg.ResultLimit,
	)
	if err != nil {
		return nil, err
	}

	defer func() { _ = rows.Close() }()

	var items []ListListsRow

	for rows.Next() {
		var i ListListsRow

		if err := rows.Scan(
			&i.ID,
			&i.Scope,
			&i.Name,
			&i.Description,
			&i.ClosesAt,
			&i.CreatedAt,
			&i.LastUpdatedAt,
			&i.ArchivedAt,
			&i.FilteredCount,
			&i.TotalCount,
		); err != nil {
			return nil, err
		}

		items = append(items, i)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return items, nil
}

